sys_script_include.script:
var BaseResolver = Class.create();
BaseResolver.prototype = {
    table_name: "",
    table_column: "name",
	actor:"",

    initialize: function(tableName, tableColumn) {
        if (!tableName) throw "tableName required";
		if (!tableColumn) throw "tableColumn required";
        this.table_name = tableName;
        this.table_column = tableColumn;
    },

    // Single match found:
    // {
    //  "valid": true,
    //  "ref": {
    //    "display":"140 George Street, Sydney",
    //    "sys_id":"xxx"
    //  }
    // }
    //
    // Not found:
    // {
    //  "valid": false,
    //  "message":"..."
    // }
    //
    // Ambiguous/multiple possible matches:
    // {
	//  "value":"<part id>",
	//  "exactMatch":true|false,
    //  "valid": false,
    //  "message":"...",
    //  "refs": [
    //    {
    //      "display":"140 George Street, Sydney",
    //      "sys_id":"xxx"
    //    }, ...
    //  ]
    // }
    //
    //
    resolve: function(value, exactMatch = false, limit = 3) {

        var response = {
            "value": value,
            "exactMatch": exactMatch,
            "valid": false,
			"refs":[],
			"message":""
        };

		if(value == null) {
			response.message = "value is undefined/null";
			return response;
		}

        // An array of objects representing table rows
        // matching @value. Given a population like so:
		//
		// ["FelixStrasse", "Felix the Cat", "Londonderry"]
		//
        // then passing in ("Felix", false) will return ["FelixStrasse", "Felix the Cat"].
        // and passing in ("Felix", true) will return [].
        var refs = this._getReferences(this.table_column, value, exactMatch, limit);

        if (refs.length == 0) {
            response.message = value + " not found";
        } else if (refs.length == 1) {
            response.valid = true;
            response.refs = refs;
        }else {
            response.message =  + " is ambiguous";
            response.refs = refs;
        }
        return response;
    },


	// Returns an array; may be empty.
	//
    // [{
    //   "name":"...",
    //   "sys_id":"..."
    //   }, ...
    // ]
	//
	// Note that partial match actually means "starts with", and 
	// there is no length test.
    _getReferences: function(column_name, value, exactMatch, limit) {
		var refs = [];

        var gr = new GlideRecord(this.table_name);

        var qc = gr.addQuery(column_name, exactMatch ? "=" : "STARTSWITH", value);
		if(column_name != "name") {
			qc.addOrCondition('name', exactMatch ? "=" : "STARTSWITH", value);
		}

        gr.setLimit(limit);

        gr.query();
        while (gr.next()) {
            refs.push({
                "name": gr.getValue("name"),
                "sys_id": gr.getValue("sys_id")
            });
        }
        return refs;
    },

    type: 'BaseResolver'
};
